?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Capture master sheet</title><?php include('links.php');?><link rel="stylesheet" href="css/smartmark.css"><style>.sm-camera{max-width:760px;margin:26px auto;padding:22px;border-radius:18px;background:#fff;box-shadow:0 12px 38px #17314b1c}.sm-camera video,.sm-camera canvas{width:100%;border-radius:13px;background:#102d44}.sm-camera canvas{display:none}.sm-camera__guide{position:relative}.sm-camera__guide:after{content:"";position:absolute;inset:7%;border:2px solid #f5bd53;border-radius:12px;pointer-events:none}.sm-camera__actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:15px}.sm-camera__notice{padding:12px;border-radius:10px;background:#f3f8f8;color:#425e6c;line-height:1.5}</style></head><body class="smartmark-page"><main class="smartmark-shell"><a class="smartmark-back" href="smartmark-master.php?assessment=<?php echo $assessmentId;?>"><i class="fa fa-arrow-left"></i> Upload instead</a><section class="sm-camera"><span>Camera capture</span><h1>Photograph the master sheet</h1><p><?php echo smartmark_escape($assessment['title']);?> — keep all four page edges inside the gold frame.</p><p class="sm-camera__notice">Your camera opens only after you choose it. The photo is held in this browser tab, uploaded once for analysis, and is not stored by this camera page.</p><div class="sm-camera__guide"><video id="preview" autoplay playsinline muted></video><canvas id="photo"></canvas></div><div class="sm-camera__actions"><button id="start" class="smartmark-primary" type="button"><i class="fa fa-camera"></i> Open rear camera</button><button id="capture" class="smartmark-primary" type="button" disabled><i class="fa fa-circle"></i> Take photo</button><button id="retake" class="smartmark-secondary" type="button" hidden>Retake</button><button id="send" class="smartmark-primary" type="button" hidden>Use this photo</button></div><p id="status" aria-live="polite"></p></section></main><script>(function(){const v=document.getElementById('preview'),c=document.getElementById('photo'),s=document.getElementById('status'),start=document.getElementById('start'),capture=document.getElementById('capture'),retake=document.getElementById('retake'),send=document.getElementById('send');let stream=null,blob=null;function stop(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}}async function open(){if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){s.textContent='Camera capture needs a modern browser and HTTPS (or localhost). Use Upload instead.';return;}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false});v.srcObject=stream;capture.disabled=false;s.textContent='Camera ready. Hold the sheet flat and well lit.';}catch(e){s.textContent='Camera permission was not granted. You can use Upload instead.';}}function reset(){blob=null;c.style.display='none';v.style.display='block';capture.disabled=false;retake.hidden=true;send.hidden=true;open();}start.onclick=open;capture.onclick=function(){if(!v.videoWidth)return;c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);stop();v.style.display='none';c.style.display='block';capture.disabled=true;retake.hidden=false;send.hidden=false;c.toBlob(b=>blob=b,'image/jpeg',.92);s.textContent='Review the photo, then use it for master-sheet detection.';};retake.onclick=reset;send.onclick=async function(){if(!blob)return;send.disabled=true;s.textContent='Uploading the photo securely for analysis…';const f=new FormData();f.append('csrf','<?php echo smartmark_escape($_SESSION['smartmark_csrf']);?>');f.append('master_sheet',new File([blob],'master-sheet.jpg',{type:'image/jpeg'}));const r=await fetch('smartmark-master.php?assessment=<?php echo $assessmentId;?>',{method:'POST',body:f,credentials:'same-origin'});document.open();document.write(await r.text());document.close();};window.addEventListener('beforeunload',stop);})();</script></body></html>
